<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class Customer extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','name','code','customer_type','legal_name','first_name','last_name','email','phone','alternative_phone','website','billing_address','shipping_address','tax_identifier','business_registration_number','industry','notes','assigned_salesperson_id','status']; public function company(){return $this->belongsTo(Company::class);} public function branch(){return $this->belongsTo(Branch::class);} public function contacts(){return $this->hasMany(CustomerContact::class);} public function addresses(){return $this->hasMany(CustomerAddress::class);} public function invoices(){return $this->hasMany(SalesInvoice::class);} public function orders(){return $this->hasMany(SalesOrder::class);} public function leads(){return $this->hasMany(Lead::class);} public function opportunities(){return $this->hasMany(Opportunity::class);} public function assignedSalesperson(){return $this->belongsTo(User::class,'assigned_salesperson_id');} }
